/** Derive the band and action from a probability and a policy. */
function bandAndAction(
  p: number,
  policy: Policy,
): { band: "act" | "escalate" | "ignore"; action: "FIRE" | "ESCALATE" | "IGNORE" } {
  const band = p >= policy.act ? "act" : p >= policy.flag ? "escalate" : "ignore";
  const action = band === "act" ? "FIRE" : band === "escalate" ? "ESCALATE" : "IGNORE";
  return { band, action };
}

